import json, hashlib, re, tomllib
from pathlib import Path
from collections import Counter
from html.parser import HTMLParser

root=Path('.')
atlas=root/'reports/skill-atlas'
data=json.loads((atlas/'sources.json').read_text())
digest=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
packages=['teach','learning-plan','explain-code','explain-decisions']
for name in packages:
    package=root/name
    assert f'name: {name}\n' in (package/'SKILL.md').read_text()
    origin=tomllib.loads((package/'origin.txt').read_text())
    assert origin['skill']==name
    for d in origin.get('dependencies',[]):
        if d['kind']=='local': assert (root/d['name']/'SKILL.md').exists(),d
    for file in package.rglob('*.md'):
        for link in re.findall(r'\]\(([^)]+)\)',file.read_text()):
            if not re.match(r'https?://|#',link): assert (file.parent/link.split('#')[0]).exists(),(file,link)
    json.loads((package/'evals/cases.json').read_text())
assert not Path('how').exists() and not Path('why').exists()
actual={p.parent.name for p in root.glob('*/SKILL.md')}
assert actual=={p['name'] for p in data['repositoryInventory']['skills']}
for p in data['repositoryInventory']['skills']: assert digest(root/p['path'])==p['sha256'],p['path']
for p in data['sourceProgress']['skills'].values():
    assert not {'how','why'}&set(p['owners'])
    for e in p['evidence']:
        if 'sha256' in e and Path(e['path']).is_file(): assert digest(Path(e['path']))==e['sha256'],e['path']
assert Counter(p['status'] for p in data['sourceProgress']['skills'].values())==data['sourceProgress']['counts']
mirror=(atlas/'catalog.js').read_text().removeprefix('window.SKILL_ATLAS = ').strip().removesuffix(';')
assert json.loads(mirror)==data
registry=json.loads(Path('skills.sh.json').read_text())
def check_registry(x):
    if isinstance(x,dict):
        for k,v in x.items():
            if k=='skills' and isinstance(v,list):
                for name in v:
                    if isinstance(name,str): assert name in actual,name
            else: check_registry(v)
    elif isinstance(x,list):
        for v in x:check_registry(v)
check_registry(registry)
class Links(HTMLParser):
    def __init__(self): super().__init__();self.ids=[];self.links=[]
    def handle_starttag(self,tag,attrs):
        d=dict(attrs)
        if 'id' in d:self.ids.append(d['id'])
        if tag=='a' and 'href' in d:self.links.append(d['href'])
for file in [atlas/'index.html',atlas/'teaching-source-review.html']:
    parser=Links();parser.feed(file.read_text());assert len(parser.ids)==len(set(parser.ids))
    for link in parser.links:
        if re.match(r'https?://|mailto:|\?',link):continue
        if link.startswith('#'):
            if file.name!='index.html': assert link[1:] in parser.ids,link
        else:
            destination=file.parent/link.split('#')[0].split('?')[0]
            assert destination.is_file() or (destination/'index.html').is_file(),link
print('PASS: four package names, TOML, dependencies, relative links, evaluation JSON, registry, 35-package inventory, all current evidence hashes, catalog parity, counts, HTML IDs and local links.')
